import json
from pathlib import Path

p=Path('src/data.json');d=json.loads(p.read_text())
# Editorial descriptions explain work and tradeoffs; they are not pay forecasts.
details={
'software':('build','Software can serve many customers at a low marginal cost. Engineers who own reliable, revenue-critical systems can have greater business impact; employer and level explain much of the pay variation.','Requires problem solving, debugging unfamiliar systems and keeping software reliable as requirements change. Interviews often add timed coding and design constraints.',['Fix scoped bugs, write tests and learn code review.','Own a feature from requirements through deployment and support.','Design components, investigate incidents and mentor engineers.','Coordinate technical direction, delivery risks and decisions across a team.'],['Write correct, readable code and explain tests.','Ship complete features and troubleshoot production issues.','Show sound design decisions and make teammates more effective.','Balance business priorities, system risk and engineering capacity.'],'Build two well-tested projects and explain your own decisions before collecting more certificates.',['coding','building','systems']),
'data':('analyze','Reliable analysis can improve pricing, operations and customer decisions. Strong SQL, domain knowledge and clear business communication increase the usefulness of your work.','Messy data, ambiguous metrics, statistical mistakes and stakeholder questions make this more than producing charts.',['Clean data, validate spreadsheets and write basic queries.','Own recurring reporting and explain metric changes.','Design analyses, review data quality and guide junior analysts.','Set analytics priorities and help teams use evidence in decisions.'],['Build reproducible SQL and verify every metric.','Frame a business question and communicate uncertainty.','Connect experiments and recommendations to decisions.','Build reliable analytics processes and coach others.'],'Start with SQL and one business dataset. Explain three decisions your analysis could change.',['data','math','business']),
'ml':('analyze','Scarce combinations of modelling, software engineering and deployment can be valuable when they improve a real product. Research hype alone does not establish commercial value.','Needs mathematics, rigorous evaluation, reproducibility and reliable deployment; weak validation can produce impressive but unusable models.',['Prepare datasets and reproduce a baseline with supervision.','Train, evaluate and deploy a model against a measurable goal.','Own model lifecycle, failure analysis and production quality.','Set technical direction and prioritize ML work against simpler alternatives.'],['Understand probability, linear algebra and data leakage.','Write tested inference services and evaluate holdout results.','Monitor drift, latency, cost and stakeholder outcomes.','Coach a team and decide when ML is worth using.'],'Master Python, statistics and baselines first. A smaller reproducible project is more persuasive than an unexplained model.',['data','math','coding','research']),
'cyber':('systems','Security work can reduce disruption, fraud and regulatory exposure. Pay can grow with scarce defensive expertise and responsibility for critical systems.','Requires systems knowledge, continuous learning and careful judgement under uncertainty; realistic incidents are not tidy textbook questions.',['Triage alerts and document evidence under supervision.','Investigate incidents and improve detection rules.','Engineer controls, threat models and response processes.','Prioritize security risks and coordinate cross-team response.'],['Learn networking, Linux and careful documentation.','Distinguish a real incident from noise and explain evidence.','Build effective defenses and validate their coverage.','Communicate risk, lead incident response and mentor analysts.'],'Use authorized labs and defensive projects. Never test systems without permission.',['systems','research','coding']),
'cloud':('systems','Availability, release speed and infrastructure cost affect the whole business. Engineers who improve reliability and operate large platforms may have wider scope.','Requires networking, operating systems, automation and incident response; changes must balance availability, security and cost.',['Resolve scoped cloud support tickets and learn runbooks.','Automate deployments and maintain infrastructure.','Own reliability, observability and recovery design.','Lead platform strategy and incident learning across teams.'],['Use Linux, Git and basic networking confidently.','Create repeatable CI/CD and infrastructure changes.','Prove recovery plans, cost awareness and measurable reliability.','Reduce recurring toil and make other teams successful.'],'Deploy a small app with monitoring and a recovery plan before chasing multiple cloud certifications.',['systems','coding','building']),
'ux':('design','Design can improve usability, conversion and adoption. Research quality, product judgement and influence across teams can matter more than polished mockups alone.','Requires finding real user problems, testing assumptions and explaining tradeoffs rather than relying on personal taste.',['Assist research, wireframes and design-system tasks.','Own the design of a feature and run usability sessions.','Lead a complex user journey and mentor designers.','Set design direction and align teams on user experience.'],['Create accessible, understandable flows.','Use user evidence and explain iterations.','Connect usability decisions to product outcomes.','Coach designers and influence cross-team priorities.'],'Show one complete case study with evidence, changes and limitations; do not present only final screens.',['design','people','building']),
'product':('business','Good product decisions can improve revenue, retention or efficiency. Pay rises with the scale of decisions and accountability, not just the job title.','Problems are ambiguous and involve competing user, technical and business needs; results depend on collaboration rather than personal authority.',['Gather requirements, analyze data and document findings.','Own a product problem, metrics and prioritised backlog.','Coordinate a larger product area and difficult tradeoffs.','Set product strategy and align teams on outcomes.'],['Write clear requirements and learn SQL and metrics.','Run discovery and measure outcomes rather than output.','Prioritize across teams and handle uncertainty.','Develop business judgement and coach product teams.'],'Practice product teardowns and data-backed cases. Entry often starts in an analyst or operations role.',['business','people','data']),
'research':('research','Specialised knowledge and the ability to generate reproducible evidence can be valuable in selected labs and industries. Academic stipends, grants and salaries follow different structures.','Requires sustained subject depth, handling inconclusive results and completing long training pathways; publication and funding are competitive.',['Support data collection, experiments and literature reviews.','Complete postgraduate coursework and a supervised dissertation.','Develop an original research question and defend evidence.','Lead research, teach or translate findings into applied work.'],['Read critically and keep reproducible records.','Develop methods, statistics and academic writing.','Design independent studies and explain limitations.','Supervise people, secure support and build a research programme.'],'Test your interest with a supervised mini-project before committing to a long research degree.',['research','math','science']),
'embedded':('build','Firmware links hardware and software in products where timing, power and safety can matter. Scarce debugging and systems expertise can command a premium.','Constrained memory, hardware behavior and timing faults make debugging more difficult than ordinary desktop programming.',['Implement scoped firmware changes and run hardware tests.','Own a device feature, protocol or driver.','Design robust firmware architecture and solve difficult timing faults.','Coordinate hardware-software integration and technical direction.'],['Use C, bit operations and measurement tools.','Understand interrupts, protocols and real-time constraints.','Prove reliability, low-power behavior and test coverage.','Align device design, safety constraints and release planning.'],'Build one sensor project and document failed experiments, measurements and fixes.',['building','systems','coding']),
'vlsi':('build','Semiconductor projects require specialised knowledge and expensive design cycles. Verification, timing and physical-design expertise can reduce costly errors.','Strong digital foundations, specialised tools and complex verification are required; mistakes can be expensive and training can be lengthy.',['Learn a flow and verify a small RTL block.','Own verification or design of a block.','Handle subsystem integration, coverage and timing closure.','Guide chip architecture or verification strategy across teams.'],['Understand digital logic and write solid testbenches.','Use assertions, coverage and synthesis concepts.','Resolve CDC, timing and integration issues.','Balance performance, power, area and project risks.'],'Start with digital logic and HDLBits. Treat specialised tool access and formal training as part of the plan.',['building','systems','math']),
'electrical':('build','Power and electrical systems support essential infrastructure. Responsibility for safety, complex projects and regulated operations can increase the scope of a role.','Requires circuit and machine fundamentals, calculations, safety discipline and practical constraints; some roles add competitive recruitment exams.',['Assist inspections, drawings and engineering calculations.','Own an electrical design or maintenance area.','Coordinate a project, protection study or reliability improvement.','Lead engineering teams and manage technical and safety risk.'],['Read drawings and validate calculations.','Apply protection, machines and control fundamentals.','Document safe decisions and manage project interfaces.','Develop leadership, budgets and cross-discipline judgement.'],'Pair theory with supervised practical exposure and clearly documented simulations.',['building','math','field']),
'mechanical':('build','Manufacturing quality, product reliability and cost can be influenced by sound design. Domain expertise and responsibility for complex products can increase pay.','Design must satisfy loads, tolerances, manufacturing constraints, cost and validation; CAD skills alone are not enough.',['Prepare drawings and support design or manufacturing tasks.','Own a part or process from requirements to validation.','Lead a subsystem, failure investigation or manufacturing improvement.','Guide engineering strategy, teams and delivery.'],['Learn drawings, materials and engineering calculations.','Apply tolerances, DFM and disciplined validation.','Connect design choices to cost and reliability.','Coach engineers and manage project tradeoffs.'],'Create a manufacturable assembly with calculations and validation, not just attractive CAD renders.',['building','math','field']),
'civileng':('build','Project scale, design responsibility and execution risk affect compensation. Licensed expertise and the ability to deliver quality infrastructure can increase scope.','Requires integrating structures, materials, ground conditions, estimates, standards and site safety under real constraints.',['Support measurements, site checks and quantity estimates.','Own a design, site package or planning workstream.','Coordinate contractors, budgets, schedules and quality.','Lead projects and manage commercial and engineering risk.'],['Read drawings and verify quantities.','Apply design fundamentals, quality checks and planning.','Document decisions and coordinate multidisciplinary work.','Manage contracts, stakeholders, safety and delivery.'],'Combine a quantity estimate and schedule with a real or supervised case study.',['building','field','math']),
'finance':('business','Accurate financial analysis supports capital allocation and business control. Specialised modelling, compliance knowledge and decision scope can raise value.','Requires precise accounting, careful assumptions and a strong link between financial numbers and real business activity.',['Reconcile records and support reporting.','Own financial analysis, forecasts or controls.','Review models and advise a business area.','Lead planning, controls and financial decision support.'],['Master statements, Excel and checking your work.','Build robust forecasts and explain assumptions.','Improve controls and connect analysis to action.','Coach teams and communicate risk to leadership.'],'Build a checked model of one real company and explain how cash differs from profit.',['business','finance','data']),
'ca':('business','The qualification and accountable work in audit, tax and finance can be valuable. Client complexity, specialisation and leadership drive large pay differences.','Multiple examinations, practical training and professional standards require sustained preparation; passing a stage does not complete the qualification.',['Study and train under the relevant ICAI scheme.','Perform qualified audit, tax or finance work within competence.','Own complex engagements or a specialist finance area.','Lead client relationships, a practice or a finance function.'],['Build accounting, law and exam-writing foundations.','Apply standards and document professional judgement.','Develop industry specialisation and quality review skills.','Demonstrate ethics, client management and team leadership.'],'Follow the current ICAI scheme and free Board of Studies material; plan revision around written practice.',['finance','business','research']),
'marketing':('business','Measurable customer acquisition, retention and brand results can influence business growth. Responsible experiment design and channel expertise can improve value.','Attribution is imperfect and channels change; results depend on customer understanding and controlled testing, not posting frequently.',['Support content, research and campaign operations.','Own a campaign or channel and its reporting.','Coordinate growth experiments and budgets.','Set marketing strategy and develop a team.'],['Learn copywriting, SEO and basic measurement.','Report clear funnel metrics and run useful tests.','Manage budgets and distinguish correlation from impact.','Align brand, growth and commercial priorities.'],'Create one small campaign case study with an honest baseline and results.',['business','design','people']),
'lawyer':('research','Legal expertise can influence risk, negotiations and dispute outcomes. Client base, specialisation, employer and professional standing create wide pay differences.','Requires precise reading, research, procedural knowledge, ethical duties and often a long supervised learning period.',['Conduct supervised research, drafting and internship tasks.','Handle assigned matters or compliance work within authorised practice.','Lead a practice area or complex matter and supervise associates.','Guide major legal strategy, client relationships and a team.'],['Read cases carefully and write concise research memos.','Develop drafting, procedure and professional judgement.','Build specialisation, negotiation and review skills.','Demonstrate ethics, client trust and mentoring.'],'Use supervised internships and real legal writing; confirm bar and practice requirements before offering services.',['research','people','business']),
'pharmacist':('science','Patient safety, regulatory quality and specialised pharmaceutical knowledge matter to employers. Qualification, industry and responsibility affect pay.','Scientific accuracy, documentation and professional regulations are essential; different pharmacy roles require different registration and skills.',['Complete supervised training and quality documentation tasks.','Perform eligible pharmacy or regulatory work within competence.','Own a specialist process, quality review or regulatory area.','Lead a pharmacy, regulatory team or quality function.'],['Strengthen pharmaceutical fundamentals and documentation.','Meet registration rules and learn quality systems.','Develop review, audit and specialist regulatory judgement.','Coach teams and manage quality and compliance risk.'],'Choose the role first: community pharmacy, production, quality and regulatory affairs have different preparation needs.',['science','research','people']),
'nurse':('people','Specialised clinical competence and leadership can influence pay, but sector, location and employer scales are major factors. Academic videos do not confer practice authority.','Requires clinical skills, safe decisions, communication and emotional resilience; training and registration are essential.',['Develop approved clinical skills under supervision.','Deliver nursing care within registration and employer protocols.','Coordinate specialist care and support junior staff.','Lead a unit, quality improvement or nursing education.'],['Master curriculum, safety and careful handover.','Demonstrate safe practice and escalation.','Develop specialty skills and evidence-based improvement.','Build staffing, mentoring and clinical leadership skills.'],'Use lecture videos to support approved training, never to replace supervised clinical practice.',['people','science','service']),
'doctor':('science','Lengthy specialist training and clinical responsibility can affect compensation. Sector, specialty, location and practice model create large differences.','Requires extensive supervised education, registration, clinical judgement and ongoing assessment; entrance selection is highly competitive.',['Complete approved clinical training and internship.','Practice within registration and role-specific competence.','Complete supervised postgraduate specialty training.','Lead specialist care, teaching or a clinical service.'],['Build clinical foundations and patient-safety habits.','Meet registration requirements and communicate clearly.','Develop specialist judgement through approved training.','Demonstrate quality, ethics, teaching and service leadership.'],'Follow NMC/NBEMS and your institution. Protect patient privacy and use videos only as a supplement to training.',['science','people','research']),
'agritech':('field','Agricultural expertise can improve productivity and supply-chain decisions. Pay depends on the type of organisation and whether the role creates measurable field or business outcomes.','Field variability, seasonality, local constraints and adoption make solutions harder than a model or business plan suggests.',['Collect field data and assist supervised projects.','Own a crop, field or agricultural analysis workstream.','Coordinate programmes, extension or agribusiness operations.','Lead products, field teams or agricultural programmes.'],['Understand agronomy and collect reliable field data.','Translate analysis into practical local recommendations.','Measure adoption, costs and programme results.','Build partnerships, team leadership and business judgement.'],'Talk to users and validate field constraints before proposing an AgriTech solution.',['field','science','business']),
'hospitalitycareer':('people','Operational reliability, guest satisfaction and revenue management can improve outcomes. Pay varies widely by employer, property, city and service model.','Requires calm service recovery, teamwork, safety and consistent execution under changing guest demand.',['Learn supervised front-office or operations tasks.','Own a shift, process or guest-service area.','Coordinate departments, service quality and budgets.','Lead a property or operations function.'],['Develop communication and basic operations discipline.','Resolve guest issues and learn inventory and revenue basics.','Improve service processes and coach a team.','Manage financial, people and quality outcomes.'],'Document service recovery and operations improvements from internships, not only course certificates.',['people','business','service']),
'public':('service','Government pay usually follows the service and notified pay level, rather than an employer bidding for a skill. Seniority, promotion rules and allowances can change compensation.','Broad examinations, constrained vacancies and multiple selection stages make entry difficult. After selection, professional performance and service rules govern progression.',['Prepare for a specific notification and verify eligibility.','Complete selection, allocation and service training when appointed.','Handle field or departmental responsibilities and supervision.','Take senior administrative responsibilities under the service rules.'],['Build subject knowledge, aptitude and disciplined revision.','Develop writing, integrity and service-specific skills.','Show sound decisions, public communication and team management.','Develop policy, coordination and institutional leadership.'],'Choose a specific exam and backup path. Qualifying one test is not a job appointment.',['service','research','people']),
'bioindustry':('science','Specialised research methods, quality systems and reliable scientific work can be valuable. Advanced roles often need postgraduate training and substantial experience.','Experiments are uncertain and sensitive to controls, contamination and interpretation; formal lab training is essential.',['Support approved experiments and lab documentation.','Own a defined study, quality task or analysis.','Develop methods, review evidence and mentor researchers.','Lead research programmes or a quality function.'],['Learn safety, controls and accurate records.','Make analyses reproducible and understand limitations.','Develop independent methods and review skills.','Manage projects, people and research priorities.'],'Seek supervised lab exposure and pair it with statistics and reproducible analysis.',['science','research','data'])
}
for c in d['careers']:
    theme,pay,diff,work,growth,advice,interests=details[c['id']]
    c.update(theme=theme,payWhy=pay,difficultyWhy=diff,advice=advice,interests=interests,sectors=['government'] if c['id']=='public' else ['private','government'] if c['id'] in ['research','electrical','mechanical','civileng','pharmacist','nurse','doctor','agritech','bioindustry','embedded'] else ['private'])
    c['progression']=[{'role':c['future'][i],'work':work[i],'skills':growth[i],'evidence':['Consistent work quality, learning and reliable documentation.','Independently delivered work, useful feedback and dependable collaboration.','Broader ownership, measurable improvements and helping others grow.','Sound decisions across teams, sustained outcomes and effective mentoring.'][i]} for i in range(4)]
    c['references']=[{'title':'GitLab public role & career framework — example of employer-specific progression','url':'https://handbook.gitlab.com/job-families/engineering/development/'}] if c['id'] in ['software','cloud','cyber','data','ml','product','ux'] else [{'title':'National Career Service — occupation and career information','url':'https://www.ncs.gov.in/'}]

